import 'server-only';

import { createAdminClient } from '@/lib/supabase/admin';
import { isDevInboxEnabled } from './dev-inbox.js';

/**
 * The other half of the development inbox.
 *
 * Order notifications are sent by FakeSmsProvider inside this Next.js process,
 * so they land in the in-memory buffer (./dev-inbox). Phone OTPs do not: they
 * are generated by Supabase Auth, which delivers them through a Send SMS Hook.
 *
 * Locally that hook is our HTTPS route, running in this same process, so its
 * messages reach the same buffer. A HOSTED project cannot call localhost, so
 * there the hook is a Postgres function that writes to public.dev_sms_outbox
 * instead (supabase/dev/sms-hook.sql). This reads that table.
 *
 * Both sources are development-only and both are gated the same way. This one
 * additionally needs the service-role key, because the table has RLS enabled
 * with no policies and no grants — there is no query a browser could make that
 * would return a row from it.
 *
 * A missing table is the normal case, not an error: it means the optional
 * hosted-development hook was never installed.
 */
export async function recentFromDatabase(limit = 25) {
  if (!isDevInboxEnabled()) return [];

  try {
    const { data, error } = await createAdminClient()
      .from('dev_sms_outbox')
      .select('id, phone, message, tag, created_at')
      .order('created_at', { ascending: false })
      .limit(limit);

    if (error) return [];

    return (data ?? []).map((row) => ({
      id: `db_${row.id}`,
      phoneNumber: row.phone,
      message: row.message,
      tag: row.tag,
      sentAt: row.created_at,
    }));
  } catch {
    return [];
  }
}
